mapper.select:
select id,
from instance_risk_metric_minute
where app_id = #{appId}
  and collect_time = (
      select max(collect_time) from instance_risk_metric_minute
      where app_id = #{appId} and collect_time between #{beginTime} and #{endTime}
  )

select m.instance_id as instanceId, m.collect_time as collectTime,
       m.keyspace_hits as keyspaceHits, m.keyspace_misses as keyspaceMisses
from instance_risk_metric_minute m
join (
    select instance_id, min(collect_time) as first_time, max(collect_time) as last_time
    from instance_risk_metric_minute
    where collect_time >= #{sinceCollectTime}
      and collect_time <= #{untilCollectTime}
    group by instance_id
) b on b.instance_id = m.instance_id
   and (m.collect_time = b.first_time or m.collect_time = b.last_time)
where m.collect_time >= #{sinceCollectTime}
  and m.collect_time <= #{untilCollectTime}
order by m.instance_id, m.collect_time
